DROP SCHEMA IF EXISTS auth CASCADE;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
INSERT INTO auth.users VALUES('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002');
CREATE TABLE public.profile(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,username text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.game(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.community(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,description text,created_by uuid REFERENCES public.profile(id),created_at timestamptz NOT NULL DEFAULT now(),city text NOT NULL,state_code varchar(2) NOT NULL,subdivision text);
CREATE TABLE public.format(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,game_id bigint NOT NULL REFERENCES public.game(id),name text NOT NULL,match_type text NOT NULL,daily_participation_limit integer NOT NULL CHECK(daily_participation_limit>0),min_players integer NOT NULL CHECK(min_players>=2),max_players integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.player(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,display_name text NOT NULL,profile_id uuid UNIQUE REFERENCES public.profile(id),community_id bigint NOT NULL REFERENCES public.community(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.game_match(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,community_id bigint NOT NULL REFERENCES public.community(id),format_id bigint NOT NULL REFERENCES public.format(id),created_by uuid REFERENCES public.profile(id),match_date date NOT NULL,approximate_end_time time,context_type text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','VERIFIED','DISPUTED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),approximate_start_time time);
CREATE TABLE public.match_participant(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,match_id bigint NOT NULL REFERENCES public.game_match(id),player_id bigint NOT NULL REFERENCES public.player(id),result text NOT NULL CHECK(result IN ('WIN','LOSS','DRAW')),team integer,UNIQUE(match_id,player_id));
CREATE TABLE public.participant_commander(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,match_participant_id bigint NOT NULL REFERENCES public.match_participant(id),external_card_id text NOT NULL,card_name text NOT NULL);
